glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);

  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;

  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D normalTex;
#endif

uniform PROPERTIES {
  vec4 uvRange;
  vec4 fluxayColor;
  float fluxaySlope;
  float time;
  float rate;
  float rotated;
}

float lerpF(float a, float b, float w) {
  return a * (1.0 - w) + b * w;
}

vec4 fluxay(vec4 texColor, vec3 normalRgb, vec2 uv, float time) {

  float x = uv.x * normalRgb.r;
  float y = uv.y * normalRgb.g;
  float width = 0.2;
  float strength = 0.6;
  float k = fluxaySlope;
  float start, left, right, comp;
  if (rotated == 0.0) {
    start = tan(time/1.414) * (1.0 + width);
    left = start - y * k - width;
    right = left + width;
    comp = x;
  } else {

    start = tan(time /1.414);

    left = start + x * k + width - 1.0;
    right = left + width;
    comp = y;
  }
  float midx = (right + left) * 0.5;
  if (comp < right && comp > left) {
    vec3 improve = fluxayColor.xyz * clamp((width - 2.0 * abs(comp - midx))/width, 0.0, 1.0) * strength;
    vec4 col = vec4(improve + vec3(texColor.r, texColor.g, texColor.b), fluxayColor.a);
    return col;
  } else {
    return texColor;
  }
}

vec4 fluxay2(vec4 texColor, vec3 normalRgb, vec2 uv, float time) {

  float width = 0.6;
  float start = tan(time/1.414);
  float strength = 1.0;
  float offset = fluxaySlope;
  float left = start - uv.y * offset - 0.3;
  float right = left + 0.6;
  float midx = max(0.0000001, (left + right) / 2.0);
  if (uv.x < right && uv.x > left) {
    vec3 improve = fluxayColor.xyz * clamp((width - 2.0 * abs(uv.x - midx))/width, 0.0, 1.0) * strength;

    vec3 result = improve + vec3(texColor.r, texColor.g, texColor.b);
    return vec4(result, fluxayColor.a);
  } else {
    return texColor;
  }
}

vec2 convertUV(vec2 uv) {
  float x = (uv.x - uvRange[0]) / uvRange[1];
  float y = (uv.y - uvRange[2]) / uvRange[3];
  return vec2(x, y);
}

void main () {
  vec4 texColor = texture2D(texture, v_uv0);
  vec2 uv = convertUV(v_uv0);
  vec3 normalRgb = texture2D(normalTex, uv).rgb;
  float t = mod((cc_time.x + time) * rate, 1.414);
  vec4 o = v_color * fluxay(texColor, normalRgb, uv, t) * texColor.a;
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

